typedef enum { IDLE, LEFT_ON, LEFT_OFF, RIGHT_ON, RIGHT_OFF, HAZARD_ON, HAZARD_OFF } SignalState;
typedef enum { TURN_NONE, TURN_LEFT, TURN_RIGHT } TurnRequest;
typedef struct { bool hazard_enabled; TurnRequest turn_request; bool phase_expired; } Inputs;
typedef struct { bool left_indicator; bool right_indicator; } Outputs;
void update_state(SignalState *state, const Inputs *in) {
  switch (*state) {
    case IDLE:
      if (in->hazard_enabled) *state = HAZARD_ON;
      else if (in->turn_request == TURN_LEFT) *state = LEFT_ON;
      else if (in->turn_request == TURN_RIGHT) *state = RIGHT_ON;
      break;
    case LEFT_ON:
      if (in->hazard_enabled) *state = HAZARD_ON;
      else if (in->turn_request != TURN_LEFT) *state = IDLE;
      else if (in->phase_expired) *state = LEFT_OFF;
      break;
    case LEFT_OFF:
      if (in->hazard_enabled) *state = HAZARD_ON;
      else if (in->turn_request != TURN_LEFT) *state = IDLE;
      else if (in->phase_expired) *state = LEFT_ON;
      break;
    case RIGHT_ON:
      if (in->hazard_enabled) *state = HAZARD_ON;
      else if (in->turn_request != TURN_RIGHT) *state = IDLE;
      else if (in->phase_expired) *state = RIGHT_OFF;
      break;
    case RIGHT_OFF:
      if (in->hazard_enabled) *state = HAZARD_ON;
      else if (in->turn_request != TURN_RIGHT) *state = IDLE;
      else if (in->phase_expired) *state = RIGHT_ON;
      break;
    case HAZARD_ON:
      if (!in->hazard_enabled) {
        if (in->turn_request == TURN_LEFT) *state = LEFT_ON;
        else if (in->turn_request == TURN_RIGHT) *state = RIGHT_ON;
        else *state = IDLE;
      } else if (in->phase_expired) *state = HAZARD_OFF;
      break;
    case HAZARD_OFF:
      if (!in->hazard_enabled) {
        if (in->turn_request == TURN_LEFT) *state = LEFT_ON;
        else if (in->turn_request == TURN_RIGHT) *state = RIGHT_ON;
        else *state = IDLE;
      } else if (in->phase_expired) *state = HAZARD_ON;
      break;
  }
}
Outputs outputs_for(SignalState state) {
  Outputs out = { false, false };
  if (state == LEFT_ON) out.left_indicator = true;
  if (state == RIGHT_ON) out.right_indicator = true;
  if (state == HAZARD_ON) { out.left_indicator = true; out.right_indicator = true; }
  return out;
}
